#!/bin/bash
# Reproducible dev-machine validation of the Wuji LibXray fork and the Xray
# configuration generated by Wuji/Core/Routing/XrayConfigBuilder.swift.
#
#   tools/libxray-patch/validation/run_validation.sh
#
# Requires a previous `tools/build_libxray.sh` run (its macOS slice is reused),
# Xcode command line tools, python3 and curl. No NetworkExtension / real device
# is needed: testXray only constructs and closes an Xray instance, and the
# traffic check runs a SOCKS inbound instead of a tun device.
set -euo pipefail
HERE="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(cd "$HERE/../../.." && pwd)"
LIB="$ROOT/tools/.cache/libXray/apple_xcframework/macosx-x86_64-arm64/libXray.a"
WORK="$ROOT/tools/.cache/validation"

if [ ! -f "$LIB" ]; then
  echo "missing $LIB — run tools/build_libxray.sh first" >&2
  exit 1
fi

mkdir -p "$WORK"
echo "Building validation driver against the patched macOS libXray slice…"
clang -O1 -o "$WORK/driver" "$HERE/driver.c" "$LIB" \
  -lresolv -lpthread -framework CoreFoundation -framework Security

echo "Building config generator from the app sources…"
swiftc -O -o "$WORK/gen_configs" \
  "$ROOT/Wuji/Core/Models/Models.swift" \
  "$ROOT/Wuji/Core/Routing/XrayConfigBuilder.swift" \
  "$HERE/config_main.swift"

ASSET_DIR="$WORK/assets"
rm -rf "$ASSET_DIR"
mkdir -p "$ASSET_DIR"
python3 "$HERE/extract_geoip_asset.py" \
  "$ROOT/Wuji/Resources/geoip.dat.gz" "$ASSET_DIR/wuji-geoip-validate.dat" cn private

rm -rf "$WORK/configs"
"$WORK/gen_configs" "$WORK/configs" "$ASSET_DIR"

python3 "$HERE/validate.py" "$WORK/driver" "$WORK/configs"
